import fs from "node:fs";


const moduleSource = `
import crypto from "node:crypto";
import { gunzipSync } from "node:zlib";
import { pool } from "./db.js";

const REPAIR_SLUG = "repair-inverted-lote001-v1";
const manifest = JSON.parse(gunzipSync(Buffer.from("", "base64")).toString("utf8"));

function normalize(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\\u0300-\\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

function sha256(value) {
  return crypto.createHash("sha256").update(String(value || ""), "utf8").digest("hex");
}

async function findOrCreateArtist(client, item) {
  const existing = await client.query(
    "SELECT id,data FROM entity_records WHERE entity_name='Artist' AND data->>'slug'=$1 ORDER BY created_date ASC,id ASC LIMIT 1",
    [item.artist_slug]
  );
  if (existing.rows[0]) return existing.rows[0];
  const data = {
    name: item.artist_name,
    slug: item.artist_slug,
    normalized_name: normalize(item.artist_name).replace(/-/g, " "),
    is_demo: false,
    is_featured: false,
  };
  const created = await client.query(
    "INSERT INTO entity_records(entity_name,data) VALUES('Artist',$1::jsonb) RETURNING id,data",
    [JSON.stringify(data)]
  );
  return created.rows[0];
}

export async function repairInvertedLote001() {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query("SELECT pg_advisory_xact_lock(hashtext($1))", [REPAIR_SLUG]);
    const done = await client.query(
      "SELECT data FROM entity_records WHERE entity_name='MigrationRepair' AND data->>'slug'=$1 LIMIT 1",
      [REPAIR_SLUG]
    );
    if (done.rows[0]?.data?.status === "completed") {
      await client.query("COMMIT");
      console.log("Lote 001 inversion repair already completed", done.rows[0].data);
      return done.rows[0].data;
    }

    const fakeArtistNames = new Map();
    const repairedIds = [];
    let repaired = 0;
    let alreadyCorrect = 0;

    for (const item of manifest) {
      const result = await client.query(
        "SELECT id,data FROM entity_records WHERE entity_name='Song' AND id::text=$1 FOR UPDATE",
        [String(item.id)]
      );
      const row = result.rows[0];
      if (!row) throw new Error("Missing affected Song " + item.id);
      const song = row.data || {};

      if (normalize(song.title) === normalize(item.title) && normalize(song.artist_name) === normalize(item.artist_name)) {
        alreadyCorrect += 1;
        repairedIds.push(String(row.id));
        continue;
      }
      if (normalize(song.title) !== normalize(item.before_title) || normalize(song.artist_name) !== normalize(item.before_artist)) {
        throw new Error("Metadata precondition failed for Song " + item.id);
      }
      if (!item.allow_metadata_only) {
        const content = song.content_raw || song.tablature || "";
        if (!item.content_hash || sha256(content) !== item.content_hash) {
          throw new Error("Content hash precondition failed for Song " + item.id);
        }
      }

      const conflict = await client.query(
        "SELECT id FROM entity_records WHERE entity_name='Song' AND id<>$1 AND data->>'artist_slug'=$2 AND data->>'slug'=$3 LIMIT 1",
        [row.id, item.artist_slug, item.slug]
      );
      if (conflict.rows[0]) {
        throw new Error("Correct destination already exists for Song " + item.id);
      }

      const artist = await findOrCreateArtist(client, item);
      const patch = {
        title: item.title,
        slug: item.slug,
        artist_name: item.artist_name,
        artist_slug: item.artist_slug,
        artist_id: String(artist.id),
        seo_title: (item.title + " - Acordes y tablatura | " + item.artist_name + " | GuitarraIA").slice(0, 70),
        seo_description: ("Aprende a tocar " + item.title + " de " + item.artist_name + " en guitarra. Acordes, tonalidad, cejilla y práctica en GuitarraIA.").slice(0, 160),
        meta_title: (item.title + " - Acordes y tablatura | " + item.artist_name + " | GuitarraIA").slice(0, 70),
        meta_description: ("Aprende a tocar " + item.title + " de " + item.artist_name + " en guitarra. Acordes, tonalidad, cejilla y práctica en GuitarraIA.").slice(0, 160),
        seo_canonical_path: "/" + item.artist_slug + "/" + item.slug,
        repaired_by: REPAIR_SLUG,
        repaired_at: new Date().toISOString(),
      };
      await client.query(
        "UPDATE entity_records SET data=data || $2::jsonb,updated_date=NOW() WHERE id=$1",
        [row.id, JSON.stringify(patch)]
      );
      repaired += 1;
      repairedIds.push(String(row.id));

      if (song.artist_id) {
        const id = String(song.artist_id);
        if (!fakeArtistNames.has(id)) fakeArtistNames.set(id, new Set());
        fakeArtistNames.get(id).add(normalize(song.artist_name));
      }
    }

    if (repaired + alreadyCorrect !== manifest.length || manifest.length !== 499) {
      throw new Error("Repair count mismatch: " + JSON.stringify({ repaired, alreadyCorrect, manifest: manifest.length }));
    }

    const deletedArtistIds = [];
    const retainedArtistIds = [];
    for (const [artistId, expectedNames] of fakeArtistNames.entries()) {
      const result = await client.query(
        "SELECT id,data FROM entity_records WHERE entity_name='Artist' AND id::text=$1 FOR UPDATE",
        [artistId]
      );
      const artist = result.rows[0];
      if (!artist) continue;
      const remaining = await client.query(
        "SELECT COUNT(*)::int AS count FROM entity_records WHERE entity_name='Song' AND data->>'artist_id'=$1",
        [artistId]
      );
      const nameMatches = expectedNames.has(normalize(artist.data?.name));
      if (remaining.rows[0].count === 0 && nameMatches) {
        await client.query("DELETE FROM entity_records WHERE id=$1 AND entity_name='Artist'", [artist.id]);
        deletedArtistIds.push(String(artist.id));
      } else {
        retainedArtistIds.push(String(artist.id));
      }
    }

    const audit = {
      slug: REPAIR_SLUG,
      status: "completed",
      repaired,
      already_correct: alreadyCorrect,
      manifest_count: manifest.length,
      repaired_ids: repairedIds,
      deleted_fake_artist_ids: deletedArtistIds,
      retained_artist_ids: retainedArtistIds,
      completed_at: new Date().toISOString(),
    };
    await client.query(
      "INSERT INTO entity_records(entity_name,data) VALUES('MigrationRepair',$1::jsonb)",
      [JSON.stringify(audit)]
    );
    await client.query("COMMIT");
    console.log("Lote 001 inversion repair completed", {
      repaired,
      alreadyCorrect,
      deletedFakeArtists: deletedArtistIds.length,
      retainedArtists: retainedArtistIds.length,
    });
    return audit;
  } catch (error) {
    await client.query("ROLLBACK");
    console.error("Lote 001 inversion repair rolled back", error);
    throw error;
  } finally {
    client.release();
  }
}
`;

fs.mkdirSync("server", { recursive: true });
fs.writeFileSync("server/repair-inverted-lote001.js", moduleSource.trimStart(), "utf8");

const indexPath = "server/index.js";
let index = fs.readFileSync(indexPath, "utf8");
if (!index.includes('from "./repair-inverted-lote001.js"')) {
  index = index.replace(
    'import express from "express";',
    'import express from "express";\nimport { repairInvertedLote001 } from "./repair-inverted-lote001.js";'
  );
}
if (!index.includes("await repairInvertedLote001();")) {
  index = index.replace("await initDatabase();", "await initDatabase();\nawait repairInvertedLote001();");
}
fs.writeFileSync(indexPath, index, "utf8");
console.log("Lote 001 inversion repair installed.");
